Translate("zhCN", "blackrock-mountain", {
	title = "黑石山",
	aliases = { "黑石", "黑石之山" },
	sections = {
		{
			title = "概述",
			text = [=[黑石山是一座本不该存在的火山。它漆黑而冒着浓烟，耸立在北方的{link:searing-gorge}灼热峡谷{/link}与南方的{link:burning-steppes}燃烧平原{/link}之间，山顶隐没在一片永不消散的火山灰之中。它不是世界缓慢运作的产物。它诞生于一日之间的烈火，那一天，一位{link:dwarves}矮人{/link}术士伸手去攫取一种他无法掌控的力量，从地底召唤出了一位火焰领主。

山体内部是中空的。山的中心张开一个巨大的火山口，底部是熔岩，上方悬挂着巨大的锁链，其链环宽阔得可以像桥一样行走。在那燃烧的深坑周围，{link:dark-iron-dwarves}黑铁矮人{/link}的建造者们开凿出了大厅、阶梯、{link:the-cauldron}熔炉{/link}和大门，其规模是{link:eastern-kingdoms}东部王国{/link}其他任何民族都从未企及的。下方是他们的都城。高处耸立着尖塔要塞。在更深处，连黑铁矮人都心怀恐惧地行走的地方，造就这座山的烈火仍在燃烧。

这里没有{link:alliance}联盟{/link}或{link:horde}部落{/link}的旗帜飘扬。这座山属于它的主人们，而它的主人们彼此交战。]=],
		},
		{
			title = "起源",
			text = [=[如今这座山所在的土地曾经是一片翠绿。在远古时代，当卡兹莫丹的所有{link:dwarves}矮人{/link}仍听命于{link:ironforge}铁炉堡{/link}的一位至高王时，{link:dark-iron-dwarves}黑铁氏族{/link}是他王座之下的三大氏族之一。至高王死后，铜须、蛮锤和黑铁三族为争夺他的王冠而战。铜须守住了铁炉堡。黑铁矮人在术士领主{link:ruins-of-thaurissan}索瑞森{/link}的率领下向南进入群山，建起了一座属于他们自己的城市，并以他的名字为其命名。

在{link:dark-portal}黑暗之门{/link}开启之前大约二百三十年，黑铁矮人发起了反击。索瑞森进军铁炉堡，而他的妻子、女术士莫德古德则进军蛮锤的根据地{link:grim-batol}格瑞姆巴托{/link}。两次进攻都失败了。莫德古德死在了格瑞姆巴托。索瑞森被击退于铁炉堡的大门前。随后，铜须国王麦迪朗和蛮锤国王卡德罗斯的军队一同转向南方，要彻底终结黑铁矮人的威胁。

索瑞森没有等他们到来。他悲痛而绝望，试图从世界燃烧的深处召唤出一件武器，于是编织了他一生中最伟大的法术。回应他的不是一件武器，而是一位主人。炎魔之王{link:ragnar-thunderbrew}拉格纳{/link}罗斯，火焰{link:elements}元素{/link}的领主，通过这位术士的法术被撕扯进了这个世界。他的降临让方圆数十里的群山崩裂。索瑞森城被吞没了。南方的土地被烧成灰烬，北方的土地裂开成一道冒烟的深渊。麦迪朗和卡德罗斯停下了他们的军队，班师回国，因为那里已经没有任何他们有望击败的敌人了。

在黑铁之城曾经矗立的地方，一座火山拔地而起。炎魔之王退入它熔融的核心，幸存的黑铁矮人则成了他的奴隶。]=],
		},
		{
			title = "当今",
			text = [=[这座山是一个有两个王座却没有休战的战场。

在下方的{red:blackrock-depths}黑石深渊{/red}中，{link:dark-iron-dwarves}黑铁矮人{/link}建起了他们的都城暗炉城，术士领主的继承人{red:emperor-dagran-thaurissan}达格兰·索瑞森大帝{/red}在那里以炎魔之王的名义统治着。在他的大厅之下，是{red:molten-core}熔火之心{/red}，{red:ragnaros}拉格纳罗斯{/red}在烈焰中等待，侍奉他的是他的{link:elements}元素{/link}副官们。黑铁矮人不停地锻造武器和傀儡，他们的战斗队伍深入{link:searing-gorge}灼热峡谷{/link}、{link:badlands}废土{/link}以及更远的地方。

在上方的{red:lower-blackrock-spire}黑石塔{/red}中，{link:blackrock-clan}黑石氏族{/link}的{link:orcs}兽人{/link}占据着高处。他们聚集在{red:warchief-rend-blackhand}大酋长雷德·黑手{/red}麾下，他是老大酋长黑手之子，他把他的追随者称为{link:horde}部落{/link}，自称大酋长，公然违抗{link:thrall}萨尔{/link}。{link:ogres}食人魔{/link}和{link:trolls}巨魔{/link}与他们并肩作战。在最顶端的{red:blackwing-lair}黑翼之巢{/red}中，住着黑龙{red:nefarian}奈法利安{/red}，他是{link:deathwing}死亡之翼{/link}之子，尖塔中的兽人都听他号令。

两个王座之间是敞开的火山口，双方都守卫着自己的大门。{link:magni-bronzebeard}麦格尼·铜须{/link}国王相信，他的女儿{red:princess-moira-bronzebeard}茉艾拉{/red}被囚禁在暗炉城的某处。部落已经派出猎手去对付{link:farmer-ray}雷{/link}德。来自各国的学者、法师和寻宝者聚集在山门前，而他们之中很少有人能从进去的路原路返回。]=],
		},
		{
			title = "居民",
			text = [=[• {b}{link:dark-iron-dwarves}黑铁矮人{/link}。{/b}火焰、岩石与黑暗技艺的大师。他们占据着深处，守卫着通往他们城市的道路。
• {b}火焰{link:elements}元素{/link}。{/b}炎魔之王的仆从，他们在下方的采石场和{link:the-cauldron}熔炉{/link}中行走，就像在那里劳作的{link:dwarves}矮人{/link}一样公开。
• {b}{link:blackrock-clan}黑石兽人{/link}。{/b}战争氏族中最古老的一支，仍保持着旧{link:horde}部落{/link}的方式。他们占据着尖塔和攀登尖塔的道路。
• {b}尖塔的{link:ogres}食人魔{/link}和{link:trolls}巨魔{/link}。{/b}他们作为盟友和打手为{link:farmer-ray}雷{/link}德的事业效力。
• {b}黑龙军团。{/b}奈法利安的子嗣守卫着山顶，他的雏龙和龙人在山顶的大厅中培育。
• {b}死者。{/b}并非每一个建造这座山的黑铁矮人都离开了它。至少有一位昔日的大师仍在守望着他所建造的城市。]=],
		},
		{
			title = "历史",
			text = [=[• {b}三锤之战。{/b}{link:dark-iron-dwarves}黑铁矮人{/link}与铜须和蛮锤为争夺全体{link:dwarves}矮人{/link}的统治权而战，并且失败了。
• {b}炎魔之王的降临。{/b}{link:ruins-of-thaurissan}索瑞森{/link}召唤{link:ragnar-thunderbrew}拉格纳{/link}罗斯，造就了这座山，造就了{link:searing-gorge}灼热峡谷{/link}和{link:burning-steppes}燃烧平原{/link}，并使黑铁之国沦为奴役。
• {b}暗炉城的建造。{/b}在炎魔之王的统治下，黑铁矮人在山的中心开凿出他们的新都城，并在其上建起了尖塔。他们的许多工程都出自建筑师{link:franclorn-forgewright}弗兰克罗恩·铸铁{/link}的设计。
• {b}{link:shadow-council}暗影议会{/link}。{/b}在{link:first-war}第一次战争{/link}的年代，从暗处统治{link:orcs}兽人{/link}的术士们把黑石塔作为他们的据点。{link:stormwind-city}暴风城{/link}陷落时，{link:orgrim-doomhammer}奥格瑞姆·毁灭之锤{/link}在那里向他们发难，杀死了他们中的大多数人，并俘虏了{link:gul-dan}古尔丹{/link}。
• {b}{link:horde}部落{/link}的据点。{/b}在{link:second-war}第二次战争{/link}中，毁灭之锤把尖塔作为他的部落的要塞。这座山与他自己的氏族同名，{link:blackrock-clan}黑石氏族{/link}将它作为自己的领地。
• {b}最后一战。{/b}第二次战争结束时，{link:alliance}联盟{/link}把部落逼回了这座山。在山脚下，{link:anduin-lothar}安度因·洛萨{/link}死于毁灭之锤之手。{link:turalyon}图拉扬{/link}拾起他的剑，重振了悲痛的军队，击溃了部落。幸存者被关进了{link:internment-camps}收容所{/link}，只有一小部分黑石兽人逃进了山中。
• {b}黑暗部落。{/b}在随后的岁月里，黑石兽人在{link:farmer-ray}雷{/link}德·黑手的率领下重新聚集于高处，而奈法利安和他的子嗣来到山顶，使兽人屈从于他的意志。从那以后，巨龙与炎魔之王之间争夺这座山的战争从未停止。]=],
		},
		{
			title = "山之传说",
			text = [=[• 黑石之名比{link:orcs}兽人{/link}更古老。据说毁灭之锤把他所占据的这座山与他的氏族同名视为一个好兆头。
• 悬挂在火山口上方的巨大锁链，是山门与通往暗炉城的道路之间唯一的通路。走过它们，就是走在一片火湖之上。
• {link:dark-iron-dwarves}黑铁{/link}之城的大门前有一座采石场，在那里站岗的是火焰本身。{link:morgan-s-vigil}摩根的岗哨{/link}的法师已经在那里失去了不止一位同伴。
• 在通往尖塔的道路旁的一条通道里，一颗黑色的宝珠安放在一座基座上。它上面有一个手印，除了携带其主人命令的人，它不回应任何人。
• 与他们的皇帝决裂的黑铁矮人如今自称{link:thorium-brotherhood}瑟银兄弟会{/link}。他们的铁匠在{link:searing-gorge}灼热峡谷{/link}的{link:thorium-point}瑟银哨塔{/link}设有营地，离这座山近得足以监视它的大门。]=],
		},
	},
})

Translate("zhCN", "franclorn-forgewright", {
	title = "弗兰克罗恩·铸铁",
	subtitle = "黑铁首席建筑师",
	found = "在黑石山中心的墓旁，只有亡者的灵魂才能看见",
	hint = "去山的中心寻找黑铁建筑师的墓。只有以灵魂之身行走的人才能看见守墓者。",
	allegiance = "黑铁矮人",
	aliases = { "弗兰克罗恩" },
	sections = {
		{
			title = "概述",
			text = [=[弗兰克罗恩·铸铁是{link:dark-iron-dwarves}黑铁{/link}之国的首席建筑师，这座山中处处是他的作品。他发明了以他命名的石工建造法，他夸口说——并非没有理由——半个世界的人都曾在不知不觉中走过他的造物。他作为族人的英雄死去。他却没能安息。他的灵魂仍站在族人为他修建的墓旁，就在他所规划的城市入口处，并且只向死者显现。]=],
		},
		{
			title = "意义",
			text = [=[弗兰克罗恩是{link:dark-iron-dwarves}黑铁{/link}之国内部少数愿意坦诚谈论这个国家变成了什么样子的声音之一。炎魔之王降临时，他侍奉他的国王和他的人民，并选择与他们留在一起。他眼看着{link:ragnar-thunderbrew}拉格纳{/link}罗斯的腐化渗入一个高贵种族的心灵，直到把他们逼向疯狂与邪恶。他知道那个选择的代价，也并不假装那是正确的选择。

他还掌握着这座城市本身的一个秘密。作为首席建筑师，他保管着暗炉城的万能钥匙，并把它藏在一个只有他才能打开的地方。]=],
		},
		{
			title = "事迹",
			text = [=[• 他发明了以他命名的石工建造法。
• 据他自己所说，当山的核心奉炎魔之王之命被掏空时，他建起了尖塔和一座比以往任何城市都更宏伟的{link:dwarves}矮人{/link}城市。
• 他锻造了巨锤铁狱，并将它留作己用。
• 他设计了矗立在{link:ruins-of-thaurissan}索瑞森{/link}神殿中的自己的纪念碑，碑中有一个用来存放城市万能钥匙的暗格，还有一个专为铁狱打造的空握柄。
• 尖塔完工时，他再也没有与族人一同生活下去的意愿。他作为新{link:dark-iron-dwarves}黑铁{/link}之国的英雄被安葬。]=],
		},
		{ title = "未载之事", text = "没有任何编年史记载弗兰克罗恩生于何时、死于何时，炎魔之王的降临与尖塔的完工之间相隔多少年，以及他的亲人后来怎样了。" },
	},
	chapters = {
		{
			title = "建筑师的悲伤",
			hint = "与建筑师的灵魂交谈，聆听他的故事。",
			text = [=[对于少数能看见他的访客，弗兰克罗恩毫无修饰地讲述着他的族人的故事。他相信自己别无选择。他熬过了{link:ruins-of-thaurissan}索瑞森{/link}城的毁灭，站在他的国王身旁。他和他的建造者们不眠不休地工作，建起了一座此前此后都没有{link:dwarves}矮人{/link}能够超越的城市，而在这期间，他一直眼看着他的同胞在改变。尖塔的最后一块石头落定时，他发现自己再也不想与他们生活在一起了。他的灵魂所站立的那座墓，就是他们的谢礼。]=],
		},
		{
			title = "铁狱",
			hint = "找回建筑师的锤子，并把它交还到他手中。",
			text = [=[他死后，铁狱传给了新任首席建筑师弗诺斯·达克维尔，弗兰克罗恩鄙视这个{link:dwarves}矮人{/link}动机卑劣、才能平庸。达克维尔无法驾驭这把锤子。弗兰克罗恩担心的是可能在达克维尔之后到来的建造者，一个技艺足以完全驾驭铁狱、用它造出毁灭之作的人。于是他请求杀死达克维尔，把锤子放进他雕像的握柄中。铁狱在那里被永远锁住。如果有人试图把它取回，雕像和锤子将一同碎裂。而当锤子滑入原位时，雕像底座的暗格会打开，城市的万能钥匙就躺在里面。]=],
		},
	},
	mentions = {
		{ text = "{link:dark-iron-dwarves}黑铁{/link}的遗产，建筑师的故事" },
		{ text = "{link:dark-iron-dwarves}黑铁{/link}的遗产，找回铁狱" },
	},
	bonds = {
		{ id = "fineous-darkvire", name = "弗诺斯·达克维尔", note = "他所鄙视的继任者" },
		{ id = "emperor-dagran-thaurissan", name = "达格兰·索瑞森大帝", note = "他称之为国王的统治者" },
	},
})

Translate("zhCN", "lothos-riftwaker", {
	title = "洛索斯·天痕",
	found = "在锁链尽头的一个小石室中，紧邻黑石深渊的大门",
	hint = "寻找在巨大锁链尽头的石室中等候的裂隙行者。",
	allegiance = "不详",
	aliases = { "洛索斯" },
	sections = {
		{
			title = "概述",
			text = [=[洛索斯·天痕是一名法师，他把自己的岗位设在巨大锁链尽头的一个小石室中，紧邻{link:dark-iron-dwarves}黑铁{/link}之城的大门。他是一名研究裂隙的学者。他教导说，世界的结构是脆弱的，懂得足够多的人就能把它撕开。他说，就在离他站立之处不到两步的地方，已经有这样一道裂隙穿过山的深处，通往炎魔之王的巢穴。]=],
		},
		{
			title = "事迹",
			text = [=[他不会轻易打开通路。访客必须先深入{link:blackrock-mountain}黑石{/link}深渊，带回一块在炎魔之王领域入口处找到的熔火之心碎片。有了它，洛索斯就能让持有者的灵魂与裂隙调和。从那以后，只要他们开口，他就能把他们送进{red:molten-core}熔火之心{/red}，即使是以灵魂之身来找他的人也不例外。]=],
		},
		{
			title = "未载之事",
			text = [=[没有任何编年史记载洛索斯来自何方、侍奉何人，或他为何选择在{link:ragnar-thunderbrew}拉格纳{/link}罗斯的门前等候。]=],
		},
	},
	mentions = {
		{ text = "熔火之心的调和" },
	},
})

Translate("zhCN", "overmaster-pyron", {
	title = "征服者派隆",
